--
-- База данных: `pdd`
--
CREATE DATABASE IF NOT EXISTS `pdd` DEFAULT CHARACTER SET utf8 COLLATE utf8_general_ci;
USE `pdd`;

DELIMITER $$
--
-- Процедуры
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `GenerateQuestions` ()  BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE cat CHAR(1);
    DECLARE q_id INT;
    DECLARE correct_answer_index INT;
    DECLARE j INT;

    WHILE i <= 800 DO
                SET cat = ELT((i-1) % 4 + 1, 'A', 'B', 'C', 'D');

                INSERT INTO questions (text, category, image_url)
        VALUES (CONCAT('Вопрос ПДД №', i, ' (категория ', cat, ') — замените на реальный текст'), cat, NULL);

        SET q_id = LAST_INSERT_ID();

                SET correct_answer_index = FLOOR(RAND() * 4);

                SET j = 0;
        WHILE j < 4 DO
            INSERT INTO answers (question_id, text, is_correct, sort_order)
            VALUES (
                q_id,
                CONCAT('Вариант ответа ', CHAR(65+j), ' для вопроса ', i, ' (', IF(j = correct_answer_index, 'правильный', 'неправильный'), ')'),
                IF(j = correct_answer_index, TRUE, FALSE),
                j
            );
            SET j = j + 1;
        END WHILE;

        SET i = i + 1;
    END WHILE;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `generate_questions` ()  BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE cat CHAR(1);
    DECLARE q_id INT;

    WHILE i <= 800 DO
                SET cat = ELT((i - 1) % 4 + 1, 'A', 'B', 'C', 'D');
        
                INSERT INTO questions (text, category, image_url)
        VALUES ('Пока ещё не завершил', cat, '/images/default.png');
        
        SET q_id = LAST_INSERT_ID();
        
                INSERT INTO answers (question_id, text, is_correct, sort_order) VALUES
            (q_id, 'Пока ещё не завершил', TRUE,  0),
            (q_id, 'Пока ещё не завершил', FALSE, 1),
            (q_id, 'Пока ещё не завершил', FALSE, 2),
            (q_id, 'Пока ещё не завершил', FALSE, 3),
            (q_id, 'Пока ещё не завершил', FALSE, 4);
        
        SET i = i + 1;
    END WHILE;
END$$

DELIMITER ;

