CREATE TABLE `access_keys` (
  `id` int(11) NOT NULL COMMENT 'Уникальный идентификатор ключа',
  `key_value` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Ключ доступа (например, ZdaRf)',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Описание (инструктор, группа и т.д.)',
  `category` char(1) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'B' COMMENT 'A, B, C, D',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Активен ли ключ',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Ключи доступа для входа в экзамен';

