-- --------------------------------------------------------

--
-- Структура таблицы `exam_results`
--

CREATE TABLE `exam_results` (
  `id` int(11) NOT NULL COMMENT 'Уникальный идентификатор результата',
  `access_key_id` int(11) NOT NULL COMMENT 'Ссылка на ключ доступа, использованный при сдаче',
  `score` int(11) NOT NULL COMMENT 'Количество правильных ответов',
  `total_questions` int(11) NOT NULL COMMENT 'Общее количество вопросов в экзамене',
  `passed` tinyint(1) GENERATED ALWAYS AS ((`score` >= (`total_questions` * 0.8))) STORED COMMENT 'Сдано/не сдано (80% порог)',
  `exam_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Дата и время завершения экзамена'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='История попыток сдачи экзамена';

--
-- Дамп данных таблицы `exam_results`
--

INSERT INTO `exam_results` (`id`, `access_key_id`, `score`, `total_questions`, `passed`, `exam_date`) VALUES
(2, 2, 0, 20, 0, '2026-05-24 16:20:01'),
(4, 2, 0, 20, 0, '2026-05-24 16:33:07');

-- --------------------------------------------------------

--
-- Структура таблицы `questions`
--

CREATE TABLE `questions` (
  `id` int(11) NOT NULL COMMENT 'Уникальный идентификатор вопроса',
  `text` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Текст вопроса',
  `category` char(1) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Категория: A, B, C, D',
  `image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL изображения (опционально)',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Дата создания',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Дата последнего обновления'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Таблица вопросов ПДД';

